import axios from 'axios';

// В Docker-сети используем имя сервиса вместо localhost
const api = axios.create({
  baseURL: 'http://backend:3001/api',  // Прямой доступ к бэкенду через имя сервиса
});

// Логирование запросов и ответов
api.interceptors.request.use(request => {
  console.log('Отправка запроса:', request.url);
  return request;
});

api.interceptors.response.use(response => {
  console.log('Получен ответ:', response.status, response.data);
  return response;
}, error => {
  console.error('Ошибка в ответе:', error.message);
  return Promise.reject(error);
});

// Функция для получения матчей с кэшированием в localStorage
const fetchMatches = async () => {
  console.log('Запрос матчей...');
  const cachedMatches = localStorage.getItem('matches');
  const cachedTime = localStorage.getItem('matchesTimestamp');
  const currentTime = Date.now();

  // Проверяем срок хранения данных (например, 5 минут)
  if (cachedMatches && cachedTime && currentTime - parseInt(cachedTime) < 5 * 60 * 1000) {
    // Если данные есть в localStorage и они свежие
    console.log('Загружены данные из localStorage');
    return JSON.parse(cachedMatches);
  }

  // Если данных нет или они устарели — делаем запрос к API
  try {
    console.log('Отправка запроса к API /matches/live');
    const response = await api.get('/matches/live');

    // Если API возвращает пустые данные, можно вернуть старые данные или пустой массив
    if (!response.data || response.data.length === 0) {
      console.warn('API вернуло пустые данные');
      return cachedMatches ? JSON.parse(cachedMatches) : [];
    }

    // Сохраняем полученные данные в localStorage
    localStorage.setItem('matches', JSON.stringify(response.data));
    localStorage.setItem('matchesTimestamp', currentTime.toString()); // Сохраняем метку времени
    console.log('Данные получены с API и сохранены в localStorage');
    return response.data;
  } catch (error) {
    console.error('Ошибка при запросе live матчей:', error);
    // Если ошибка, можно вернуть старые данные или пустой массив
    return cachedMatches ? JSON.parse(cachedMatches) : [];
  }
};

export { fetchMatches };
